/* script.js */
if(!document.querySelector('link[rel~="icon"]')){const favicon=document.createElement('link');favicon.rel='icon';favicon.type='image/svg+xml';favicon.href=location.pathname.includes('/feira-de-santana/')?'../assets/favicon.svg':'assets/favicon.svg';document.head.appendChild(favicon);}
const observer = new IntersectionObserver((entries) => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('show'); observer.unobserve(entry.target); } }), { threshold: .12 });
document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
const header = document.querySelector('.header');
const updateHeaderState = () => header?.classList.toggle('is-scrolled', window.scrollY > 18);
updateHeaderState();
window.addEventListener('scroll', updateHeaderState, { passive: true });
const menuToggle = document.querySelector('.menu-toggle');
const headerNav = document.querySelector('.header-nav');
menuToggle?.addEventListener('click', () => {
const isOpen = header.classList.toggle('menu-open');
menuToggle.setAttribute('aria-expanded', String(isOpen));
menuToggle.setAttribute('aria-label', isOpen ? 'Fechar menu' : 'Abrir menu');
});
headerNav?.querySelectorAll('a').forEach(link => link.addEventListener('click', () => {
header.classList.remove('menu-open');
menuToggle?.setAttribute('aria-expanded', 'false');
menuToggle?.setAttribute('aria-label', 'Abrir menu');
}));
document.querySelectorAll('.video-card').forEach((card,index) => {
card.dataset.videoIndex = card.dataset.videoIndex || String(index + 1);
card.dataset.videoId = card.dataset.videoId || `depoimento_${index + 1}`;
card.dataset.videoTitle = card.dataset.videoTitle || `Depoimento ${index + 1}`;
card.dataset.videoLocation = card.dataset.videoLocation || 'depoimentos';
card.addEventListener('click', () => {
const source = card.dataset.video;
if (!source || card.querySelector('video')) return;
const video = document.createElement('video');
video.src = source;
video.controls = true;
video.playsInline = true;
video.preload = 'metadata';
video.dataset.videoIndex = card.dataset.videoIndex;
video.dataset.videoId = card.dataset.videoId;
video.dataset.videoTitle = card.dataset.videoTitle;
video.dataset.videoLocation = card.dataset.videoLocation;
video.setAttribute('aria-label', card.getAttribute('aria-label') || 'Depoimento em vídeo');
card.replaceChildren(video);
card.classList.add('is-playing');
window.drAlexBindVideoTracking?.(video);
video.play().catch(() => {});
});
});
/* carousel.js */
const track = document.querySelector('.review-track');
const heading = document.querySelector('.testimonials-heading');
if (track && heading) {
const controls = document.createElement('div');
controls.className = 'carousel-controls';
controls.innerHTML = '<button class="carousel-button carousel-button--previous" type="button" aria-label="Avaliações anteriores">←</button><button class="carousel-button carousel-button--next" type="button" aria-label="Próximas avaliações">→</button>';
track.parentElement.appendChild(controls);
const [previous, next] = controls.querySelectorAll('button');
const move = direction => {
const card = track.querySelector('.review-card');
track.scrollBy({ left: direction * ((card?.offsetWidth || 320) + 16), behavior: 'smooth' });
};
previous.addEventListener('click', () => move(-1));
next.addEventListener('click', () => move(1));
}
const footerCopyright=document.querySelector('footer .copyright');
if(footerCopyright&&!footerCopyright.querySelector('a[href$="politica-de-privacidade.html"]')){const privacy=document.createElement('a');privacy.href=location.pathname.includes('/feira-de-santana/')?'../politica-de-privacidade.html':'politica-de-privacidade.html';privacy.textContent='Política de Privacidade';privacy.style.color='#f2c95c';privacy.style.fontWeight='700';privacy.style.textDecoration='none';footerCopyright.appendChild(document.createElement('br'));footerCopyright.appendChild(privacy);}
if(!window.__drAlexTrackingBootstrap){window.__drAlexTrackingBootstrap=true;window.dataLayer=window.dataLayer||[];window.gtag=window.gtag||function(){dataLayer.push(arguments)};gtag('js',new Date());gtag('config','G-SBQG3C8VXN');gtag('config','AW-960830346');if(!window.fbq){!function(f,b,e,v,n,t,s){n=f.fbq=function(){n.callMethod?n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,document,'script','https://connect.facebook.net/en_US/fbevents.js');fbq('init','1387568828019134');fbq('track','PageView')}const g=document.createElement('script');g.async=true;g.src='https://www.googletagmanager.com/gtag/js?id=G-SBQG3C8VXN';document.head.appendChild(g);const t=document.createElement('script');t.defer=true;t.src='assets/js/tracking.min.js';document.head.appendChild(t);}
